gLE(){return"\u0424\u0440\u0430\u0433\u043c\u0435\u043d\u0442\u044b \u041e\u0442\u043a\u0440\u043e\u0432\u0435\u043d\u0438\u0435 (2:1-3, 13-15, 27-29); (3:10-12); (5:8-9); (6:4-6); (8:3-8, 11-13); (9:1-5, 7-16, 18-21); (10:1-4, 8-11); (11:1-5, 8-15, 18-19); (12:1-5, 8-10, 12-17); (13:1-3, 6-16, 18); (14:1-3, 5-7, 10-11, 14-15, 18-20); (15:1, 4-7)."},
gLI(){return"\u041f\u0430\u043f\u0438\u0440\u0443\u0441 115 \u2013 \u044d\u0442\u043e \u0444\u0440\u0430\u0433\u043c\u0435\u043d\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u0433\u0440\u0435\u0447\u0435\u0441\u043a\u0438\u0439 \u043c\u0430\u043d\u0443\u0441\u043a\u0440\u0438\u043f\u0442 \u041d\u043e\u0432\u043e\u0433\u043e \u0417\u0430\u0432\u0435\u0442\u0430, \u043d\u0430\u043f\u0438\u0441\u0430\u043d\u043d\u044b\u0439 \u043d\u0430 \u043f\u0430\u043f\u0438\u0440\u0443\u0441\u0435, \u0442\u0430\u043a\u0436\u0435 \u0438\u0437\u0432\u0435\u0441\u0442\u0435\u043d \u043a\u0430\u043a \u041e\u043a\u0441\u0438\u0440\u0438\u043d\u0445\u0441\u043a\u0438\u0439 \u043f\u0430\u043f\u0438\u0440\u0443\u0441 #4499. \u041e\u043d \u0441\u043e\u0441\u0442\u043e\u0438\u0442 \u0438\u0437 26 \u0444\u0440\u0430\u0433\u043c\u0435\u043d\u0442\u043e\u0432 \u043a\u043e\u0434\u0435\u043a\u0441\u0430, \u0441\u043e\u0434\u0435\u0440\u0436\u0430\u0449\u0435\u0433\u043e \u0447\u0430\u0441\u0442\u0438 \u043a\u043d\u0438\u0433\u0438 \u041e\u0442\u043a\u0440\u043e\u0432\u0435\u043d\u0438\u044f. \u041e\u0440\u0438\u0433\u0438\u043d\u0430\u043b\u044c\u043d\u044b\u0435 \u0441\u0442\u0440\u0430\u043d\u0438\u0446\u044b \u0438\u043c\u0435\u043b\u0438 \u0440\u0430\u0437\u043c\u0435\u0440\u044b \u043f\u0440\u0438\u043c\u0435\u0440\u043d\u043e 15,5 \xd7 23,5 \u0441\u043c."},
gLJ(){return"\u0422\u0435\u043a\u0441\u0442 \u043d\u0430\u043f\u0438\u0441\u0430\u043d \u0433\u0440\u0435\u0447\u0435\u0441\u043a\u0438\u043c \u0443\u043d\u0446\u0438\u0430\u043b\u044c\u043d\u044b\u043c \u043f\u0438\u0441\u044c\u043c\u043e\u043c, \u0440\u0430\u0441\u043f\u043e\u043b\u043e\u0436\u0435\u043d \u0432 \u043e\u0434\u043d\u0443 \u043a\u043e\u043b\u043e\u043d\u043a\u0443 \u043d\u0430 \u0441\u0442\u0440\u0430\u043d\u0438\u0446\u0435 \u0441 33-36 \u0441\u0442\u0440\u043e\u043a\u0430\u043c\u0438. \u041e\u043d \u0441\u043b\u0435\u0434\u0443\u0435\u0442 \u0441\u0442\u0438\u043b\u044e scriptio continua \u0431\u0435\u0437 \u0440\u0430\u0437\u0434\u0435\u043b\u0435\u043d\u0438\u044f \u0441\u043b\u043e\u0432 \u0438 \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u0442 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u0435 \u0437\u043d\u0430\u043a\u0438 \u043f\u0443\u043d\u043a\u0442\u0443\u0430\u0446\u0438\u0438 \u0438 \u0441\u043e\u043a\u0440\u0430\u0449\u0435\u043d\u0438\u044f, \u0445\u0430\u0440\u0430\u043a\u0442\u0435\u0440\u043d\u044b\u0435 \u0434\u043b\u044f \u0431\u0438\u0431\u043b\u0435\u0439\u0441\u043a\u0438\u0445 \u0440\u0443\u043a\u043e\u043f\u0438\u0441\u0435\u0439 \u0442\u043e\u0433\u043e \u043f\u0435\u0440\u0438\u043e\u0434\u0430."},
gLH(){return u.r},
gLD(){return"\u0421 \u0442\u0435\u043a\u0441\u0442\u043e\u043b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u0442\u043e\u0447\u043a\u0438 \u0437\u0440\u0435\u043d\u0438\u044f, \u044d\u0442\u043e\u0442 \u043f\u0435\u0440\u0432\u043e\u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u0435\u0442 \u0430\u043b\u0435\u043a\u0441\u0430\u043d\u0434\u0440\u0438\u0439\u0441\u043a\u043e\u043c\u0443 \u0442\u0438\u043f\u0443 \u0442\u0435\u043a\u0441\u0442\u0430. \u041e\u043d \u043a\u043b\u0430\u0441\u0441\u0438\u0444\u0438\u0446\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043a\u0430\u043a \u041a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u044f I \u0441\u0440\u0435\u0434\u0438 \u043c\u0430\u043d\u0443\u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0432 \u041d\u043e\u0432\u043e\u0433\u043e \u0417\u0430\u0432\u0435\u0442\u0430. "},
gLF(){return"\u041f\u0430\u043f\u0438\u0440\u0443\u0441 115 \u0432 \u043d\u0430\u0441\u0442\u043e\u044f\u0449\u0435\u0435 \u0432\u0440\u0435\u043c\u044f \u0445\u0440\u0430\u043d\u0438\u0442\u0441\u044f \u0432 \u041c\u0443\u0437\u0435\u0435 \u042d\u0448\u043c\u043e\u043b\u0430 \u0432 \u041e\u043a\u0441\u0444\u043e\u0440\u0434\u0435, \u0412\u0435\u043b\u0438\u043a\u043e\u0431\u0440\u0438\u0442\u0430\u043d\u0438\u044f."},
