gF2(){return"\u043f\u0438\u0442\u0430\u043b\u044c\u043d\u0430 \u0447\u0430\u0441\u0442\u043a\u0430"},
gF3(){return"\u0437\u0430\u043f\u0435\u0440\u0435\u0447\u043d\u0430 \u0447\u0430\u0441\u0442\u043a\u0430"},
gF_(){return"\u0447\u0430\u0441\u0442\u043a\u0430"},
